window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c1d970e916b5bdd7"]={"versions": [{"id": "FIG-c1d970e916b5bdd7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation abgeleiteter Konfigurationsparameter (Derived Parameters) im Metamodell der AUTOSAR ECU Configuration (TPS ECUConfiguration). Das Diagramm modelliert die strukturellen Beziehungen zwischen Container- und Parameterdefinitionen, Berechnungs- und Abfrageformeln sowie Verweisen auf definierende Metamodellelemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> (spezialisiert <code>EcucContainerDef</code>): Enthält das Attribut <code>+ multipleConfigurationContainer: Boolean</code> und aggregiert über die Komposition <code>+parameter</code> mit Kardinalität <code>*</code> Instanzen von <code>EcucParameterDef</code>.\n</li><li><code>EcucParameterDef</code> (spezialisiert <code>EcucCommonAttributes</code>): Definiert Attribute <code>+ symbolicNameValue: Boolean</code> und <code>+ withAuto: Boolean [0..1]</code>. Es besitzt eine optionale Komposition <code>+derivation</code> (Kardinalität <code>0..1</code>) zu <code>EcucDerivationSpecification</code>.\n</li><li><code>EcucDerivationSpecification</code>: Bündelt Berechnungsformeln und Abfragen.\n<ul class=\"fig-list\"><li>Komposition <code>+informalFormula</code> (<code>0..1</code>) zu <code>MlFormula</code> (spezialisiert <code>Paginateable</code>).\n</li><li>Komposition <code>+calculationFormula</code> (<code>0..1</code>) zu <code>EcucParameterDerivationFormula</code> (spezialisiert <code>FormulaExpression</code>, Stereotyp <code>«atpMixedString»</code>).\n</li><li>Komposition <code>+ecucQuery</code> (<code>0..*</code>) zu <code>EcucQuery</code>.\n</li></ul>\n</li><li><code>EcucQuery</code> (spezialisiert <code>Identifiable</code>): Aggregiert per Komposition <code>+ecucQueryExpression</code> (<code>1</code>) eine <code>EcucQueryExpression</code>. Zudem referenziert <code>EcucParameterDerivationFormula</code> auf <code>EcucQuery</code> über die gerichteten Assoziationen <code>+ecucQuery</code> (<code>0..1</code>) und <code>+ecucQueryString</code> (<code>0..1</code>).\n</li><li><code>EcucQueryExpression</code> (Stereotyp <code>«atpMixedString»</code>): Verweist über gerichtete Assoziationen mit dem Stereotyp <code>«atpUriDef»</code> auf <code>EcucDefinitionElement</code>:\n<ul class=\"fig-list\"><li><code>+configElementDefGlobal</code> (<code>0..1</code>)\n</li><li><code>+configElementDefLocal</code> (<code>0..1</code>)\n</li></ul>\n</li><li><code>EcucDefinitionElement</code> (spezialisiert <code>Identifiable</code>): Enthält die variabilitätsrelevanten Attribute (<code>«atpVariation»</code>) <code>+ lowerMultiplicity: PositiveInteger</code>, <code>+ upperMultiplicity: PositiveInteger [0..1]</code> und <code>+ upperMultiplicityInfinite: Boolean [0..1]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von Laufzeit- oder Sequenzabläufen. Zur Auswertungszeit (z. B. Werkzeug-Generierungszeit / Pre-Compile / Link-Time) wird ein abgeleiteter Parameter über die in <code>EcucDerivationSpecification</code> hinterlegte <code>calculationFormula</code> berechnet. Diese Formel (<code>EcucParameterDerivationFormula</code>) greift auf definierte Abfragen (<code>EcucQuery</code>) zu, welche über <code>EcucQueryExpression</code> per URI-Referenz (<code>configElementDefGlobal</code>, <code>configElementDefLocal</code>) auf die referenzierten <code>EcucDefinitionElement</code>-Instanzen aufgelöst werden. Alternativ oder ergänzend kann eine informelle Beschreibung über <code>informalFormula</code> vorliegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Metamodellvorgabe für die Parametrierung abgeleiteter Werte in BSW-Modulen und Systembeschreibungen.\n</li><li>Die Berechnungsvorschrift ist entweder formal über <code>EcucParameterDerivationFormula</code> oder informal (<code>MlFormula</code>) anzugeben.\n</li><li>Formelausdrücke sind gemischte Textstrukturen (<code>«atpMixedString»</code>), die Ausdrücke mit Metamodellreferenzen kombinieren.\n</li><li>Verweise auf Zielelemente (<code>EcucDefinitionElement</code>) sind als AUTOSAR-URI-Referenzen (<code>«atpUriDef»</code>) mit lokaler oder globaler Auflösung spezifiziert. Multiplizitäten der Definitionselemente unterliegen der modellierten Variabilität (<code>«atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e719d5a63f80200d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation abgeleiteter Konfigurationsparameter (Derived Parameters) im Metamodell der AUTOSAR ECU Configuration (TPS ECUConfiguration). Das Diagramm modelliert die strukturellen Beziehungen zwischen Container- und Parameterdefinitionen, Berechnungs- und Abfrageformeln sowie Verweisen auf definierende Metamodellelemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> (spezialisiert <code>EcucContainerDef</code>): Enthält das Attribut <code>+ multipleConfigurationContainer :Boolean</code> und aggregiert über die Komposition <code>+parameter</code> mit Kardinalität <code>*</code> Instanzen von <code>EcucParameterDef</code>.\n</li><li><code>EcucParameterDef</code> (spezialisiert <code>EcucCommonAttributes</code>): Definiert Attribute <code>+ symbolicNameValue :Boolean</code> und <code>+ withAuto :Boolean [0..1]</code>. Es besitzt eine optionale Komposition <code>+derivation</code> (Kardinalität <code>0..1</code>) zu <code>EcucDerivationSpecification</code>.\n</li><li><code>EcucDerivationSpecification</code>: Bündelt Berechnungsformeln und Abfragen.\n<ul class=\"fig-list\"><li>Komposition <code>+informalFormula</code> (<code>0..1</code>) zu <code>MlFormula</code> (spezialisiert <code>Paginateable</code>).\n</li><li>Komposition <code>+calculationFormula</code> (<code>0..1</code>) zu <code>EcucParameterDerivationFormula</code> (spezialisiert <code>FormulaExpression</code>, Stereotyp <code>«atpMixedString»</code>).\n</li><li>Komposition <code>+ecucQuery</code> (<code>0..*</code>) zu <code>EcucQuery</code>.\n</li></ul>\n</li><li><code>EcucQuery</code> (spezialisiert <code>Identifiable</code>): Aggregiert per Komposition <code>+ecucQueryExpression</code> (<code>1</code>) eine <code>EcucQueryExpression</code>. Zudem referenziert <code>EcucParameterDerivationFormula</code> auf <code>EcucQuery</code> über die gerichteten Assoziationen <code>+ecucQuery</code> (<code>0..1</code>) und <code>+ecucQueryString</code> (<code>0..1</code>).\n</li><li><code>EcucQueryExpression</code> (Stereotyp <code>«atpMixedString»</code>): Verweist über gerichtete Assoziationen mit dem Stereotyp <code>«atpUriDef»</code> auf <code>EcucDefinitionElement</code>:\n<ul class=\"fig-list\"><li><code>+configElementDefGlobal</code> (<code>0..1</code>)\n</li><li><code>+configElementDefLocal</code> (<code>0..1</code>)\n</li></ul>\n</li><li><code>EcucDefinitionElement</code> (spezialisiert <code>Identifiable</code> und <code>AtpDefinition</code>): Enthält das Attribut <code>+ scope :EcucScopeEnum [0..1]</code> sowie die variabilitätsrelevanten Attribute (<code>«atpVariation»</code>) <code>+ lowerMultiplicity :PositiveInteger</code>, <code>+ upperMultiplicity :PositiveInteger [0..1]</code> und <code>+ upperMultiplicityInfinite :Boolean [0..1]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von Laufzeit- oder Sequenzabläufen. Zur Auswertungszeit (z. B. Werkzeug-Generierungszeit / Pre-Compile / Link-Time) wird ein abgeleiteter Parameter über die in <code>EcucDerivationSpecification</code> hinterlegte <code>calculationFormula</code> berechnet. Diese Formel (<code>EcucParameterDerivationFormula</code>) greift auf definierte Abfragen (<code>EcucQuery</code>) zu, welche über <code>EcucQueryExpression</code> per URI-Referenz (<code>configElementDefGlobal</code>, <code>configElementDefLocal</code>) auf die referenzierten <code>EcucDefinitionElement</code>-Instanzen aufgelöst werden. Alternativ oder ergänzend kann eine informelle Beschreibung über <code>informalFormula</code> vorliegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Metamodellvorgabe für die Parametrierung abgeleiteter Werte in BSW-Modulen und Systembeschreibungen.\n</li><li>Durch Spezialisierung von <code>AtpDefinition</code> ist <code>EcucDefinitionElement</code> als formales Definitionselement typisiert und verfügt über das optionale Attribut <code>scope :EcucScopeEnum [0..1]</code>.\n</li><li>Die Berechnungsvorschrift ist entweder formal über <code>EcucParameterDerivationFormula</code> oder informal (<code>MlFormula</code>) anzugeben.\n</li><li>Formelausdrücke sind gemischte Textstrukturen (<code>«atpMixedString»</code>), die Ausdrücke mit Metamodellreferenzen kombinieren.\n</li><li>Verweise auf Zielelemente (<code>EcucDefinitionElement</code>) sind als AUTOSAR-URI-Referenzen (<code>«atpUriDef»</code>) mit lokaler oder globaler Auflösung spezifiziert. Multiplizitäten der Definitionselemente unterliegen der modellierten Variabilität (<code>«atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c8e91821229145f1", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation abgeleiteter Konfigurationsparameter (Derived Parameters) im Metamodell der AUTOSAR ECU Configuration (TPS ECUConfiguration). Das Diagramm modelliert die strukturellen Beziehungen zwischen Container- und Parameterdefinitionen, Berechnungs- und Abfrageformeln sowie Verweisen auf definierende Metamodellelemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code> (spezialisiert <code>EcucContainerDef</code>): Aggregiert über die Komposition <code>+parameter</code> (Kardinalität <code>*</code>, Stereotyp <code>«atpSplitable»</code>) Instanzen von <code>EcucParameterDef</code>.\n</li><li><code>EcucParameterDef</code> (spezialisiert <code>EcucCommonAttributes</code>): Definiert Attribute <code>+ symbolicNameValue :Boolean</code> und <code>+ withAuto :Boolean [0..1]</code>. Es besitzt eine optionale Komposition <code>+derivation</code> (Kardinalität <code>0..1</code>) zu <code>EcucDerivationSpecification</code>.\n</li><li><code>EcucDerivationSpecification</code>: Bündelt Berechnungsformeln und Abfragen.\n<ul class=\"fig-list\"><li>Komposition <code>+informalFormula</code> (<code>0..1</code>) zu <code>MlFormula</code> (spezialisiert <code>Paginateable</code>).\n</li><li>Komposition <code>+calculationFormula</code> (<code>0..1</code>) zu <code>EcucParameterDerivationFormula</code> (spezialisiert <code>FormulaExpression</code>, Stereotyp <code>«atpMixedString»</code>).\n</li><li>Komposition <code>+ecucQuery</code> (<code>0..*</code>) zu <code>EcucQuery</code>.\n</li></ul>\n</li><li><code>EcucQuery</code> (spezialisiert <code>Identifiable</code>): Aggregiert per Komposition <code>+ecucQueryExpression</code> (<code>1</code>) eine <code>EcucQueryExpression</code>. Zudem referenziert <code>EcucParameterDerivationFormula</code> auf <code>EcucQuery</code> über die gerichteten Assoziationen <code>+ecucQuery</code> (<code>0..1</code>) und <code>+ecucQueryString</code> (<code>0..1</code>).\n</li><li><code>EcucQueryExpression</code> (Stereotyp <code>«atpMixedString»</code>): Verweist über gerichtete Assoziationen mit dem Stereotyp <code>«atpUriDef»</code> auf <code>EcucDefinitionElement</code>:\n<ul class=\"fig-list\"><li><code>+configElementDefGlobal</code> (<code>0..1</code>)\n</li><li><code>+configElementDefLocal</code> (<code>0..1</code>)\n</li></ul>\n</li><li><code>EcucDefinitionElement</code> (spezialisiert <code>Identifiable</code> und <code>AtpDefinition</code>): Enthält das Attribut <code>+ scope :EcucScopeEnum [0..1]</code> sowie die variabilitätsrelevanten Attribute (<code>«atpVariation»</code>) <code>+ lowerMultiplicity :PositiveInteger</code>, <code>+ upperMultiplicity :PositiveInteger [0..1]</code> und <code>+ upperMultiplicityInfinite :Boolean [0..1]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Modellierung von Laufzeit- oder Sequenzabläufen. Zur Auswertungszeit (z. B. Werkzeug-Generierungszeit / Pre-Compile / Link-Time) wird ein abgeleiteter Parameter über die in <code>EcucDerivationSpecification</code> hinterlegte <code>calculationFormula</code> berechnet. Diese Formel (<code>EcucParameterDerivationFormula</code>) greift auf definierte Abfragen (<code>EcucQuery</code>) zu, welche über <code>EcucQueryExpression</code> per URI-Referenz (<code>configElementDefGlobal</code>, <code>configElementDefLocal</code>) auf die referenzierten <code>EcucDefinitionElement</code>-Instanzen aufgelöst werden. Alternativ oder ergänzend kann eine informelle Beschreibung über <code>informalFormula</code> vorliegen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Metamodellvorgabe für die Parametrierung abgeleiteter Werte in BSW-Modulen und Systembeschreibungen.\n</li><li>Durch Spezialisierung von <code>AtpDefinition</code> ist <code>EcucDefinitionElement</code> als formales Definitionselement typisiert und verfügt über das optionale Attribut <code>scope :EcucScopeEnum [0..1]</code>.\n</li><li>Die Assoziation <code>parameter</code> von <code>EcucParamConfContainerDef</code> zu <code>EcucParameterDef</code> ist mit <code>«atpSplitable»</code> versehen, was ein Aufteilen der Parameterdefinitionen über mehrere physische ARXML-Dateien bzw. Deliverables ermöglicht.\n</li><li>Die Berechnungsvorschrift ist entweder formal über <code>EcucParameterDerivationFormula</code> oder informal (<code>MlFormula</code>) anzugeben.\n</li><li>Formelausdrücke sind gemischte Textstrukturen (<code>«atpMixedString»</code>), die Ausdrücke mit Metamodellreferenzen kombinieren.\n</li><li>Verweise auf Zielelemente (<code>EcucDefinitionElement</code>) sind als AUTOSAR-URI-Referenzen (<code>«atpUriDef»</code>) mit lokaler oder globaler Auflösung spezifiziert. Multiplizitäten der Definitionselemente unterliegen der modellierten Variabilität (<code>«atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c1d970e916b5bdd7", "to": "FIG-e719d5a63f80200d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>EcucDefinitionElement</code>: Attribut <code>+ scope :EcucScopeEnum [0..1]</code> hinzugefügt.\n</li><li><code>EcucDefinitionElement</code>: Stereotyp bzw. Supertyp <code>AtpDefinition</code> zusätzlich zu <code>Identifiable</code> ergänzt.\n</li></ul>"}, {"from": "FIG-e719d5a63f80200d", "to": "FIG-c8e91821229145f1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>EcucParamConfContainerDef</code>: Attribut <code>+ multipleConfigurationContainer :Boolean</code> entfernt.\n</li><li>Assoziation <code>+parameter</code> von <code>EcucParamConfContainerDef</code> zu <code>EcucParameterDef</code>: Stereotyp <code>«atpSplitable»</code> ergänzt.\n</li></ul>"}]};
